(function(){
  var modal = document.getElementById('searchModal');
  if(!modal) return;
  modal.addEventListener('shown.bs.modal', function(){
    var inp = document.getElementById('sl-search-input');
    if(inp) inp.focus();
  });
})();

busca_com_sugestoes.js:
(function(){
  var inp = document.getElementById('slSuggestInput');
  var list = document.getElementById('slSuggestList');
  if(!inp || !list) return;
  var timer;
  inp.addEventListener('input', function(){
    clearTimeout(timer);
    var q = this.value.trim();
    if(q.length < 2){ list.innerHTML=''; list.classList.remove('open'); return; }
    timer = setTimeout(function(){
      fetch('/feeds/posts/summary?q=' + encodeURIComponent(q) + '&max-results=5&alt=json')
        .then(function(r){ return r.json(); })
        .then(function(data){
          var entries = (data.feed && data.feed.entry) || [];
          list.innerHTML = '';
          if(!entries.length){ list.classList.remove('open'); return; }
          entries.forEach(function(e){
            var title = e.title && e.title.$t || '';
            var link = '';
            if(e.link) e.link.forEach(function(l){ if(l.rel==='alternate') link=l.href; });
            var a = document.createElement('a');
            a.href = link;
            a.className = 'sl-suggest-item';
            a.innerHTML = '<i class="bi bi-file-text me-2 opacity-50"></i>' + title;
            list.appendChild(a);
          });
          list.classList.add('open');
        }).catch(function(){});
    }, 300);
  });
  document.addEventListener('click', function(e){
    if(!document.getElementById('slSuggestWrap').contains(e.target)){
      list.classList.remove('open');
    }
  });
  inp.addEventListener('keydown', function(e){
    if(e.key === 'Enter') location.href = '/search?q=' + encodeURIComponent(inp.value);
  });
})();
